"""Synthetic check of the analysis: inject effects generated by each account into the dry-run structure."""
import json, copy, numpy as np, subprocess, sys
d = json.load(open('dry2.json'))
M = d['results']['main']; NA = d['results']['noadapt']
rng = np.random.default_rng(0)
REP = 30
def rep_list(x): return [copy.deepcopy(v) for _ in range(REP) for v in x]
for S in (M, NA):
    S['base'] = rep_list(S['base']); S['T'] = [t for _ in range(REP) for t in S['T']]; S['dL'] = [t for _ in range(REP) for t in S['dL']]
    for k in S['cond']: S['cond'][k] = rep_list(S['cond'][k])
    for k in S['dists']: S['dists'][k] = rep_list(S['dists'][k])
d['accepted'] = rep_list(d['accepted'])
DEL = [0.0] + d['settings']['DELAYS']; W = d['settings']['EARLY_W']
def F(q, x): return float(np.interp(x, q, np.linspace(0, 1, 101), left=0, right=1))
def g(gl, xT): return float(np.interp(xT, np.linspace(0, 3, 301), gl))
def setc(S, key, i, pct, noise=1.0):
    for s in range(8):
        for m in ('mBm', 'mB', 'mBabs'):
            S['cond'][key][i][s][m] = S['base'][i][s][m] * (1 + (pct + rng.normal(0, noise)) / 100)
def scenario(acc):
    for i in range(len(M['T'])):
        T = M['T'][i]; q = M['dists']['base_all'][i]['q']; gl = M['dists']['base_all'][i]['g']
        s, u = 20 + rng.normal(0, 3), -32 + rng.normal(0, 3); e = s - u
        setc(M, 'gated_0.2', i, s); setc(M, 'ungated_0.2', i, u)
        if acc == 'handover':
            setc(M, 'early_0.2', i, -e * F(q, W * T)); setc(M, 'late_0.2', i, -e * (1 - F(q, M['dL'][i])))
            for dd in DEL[1:]: setc(M, f'offset_0.2_x{dd:g}', i, s - e * F(q, dd * T))
        else:
            setc(M, 'early_0.2', i, -e * g(gl, W)); setc(M, 'late_0.2', i, -e * g(gl, W))
            for dd in DEL[1:]: setc(M, f'offset_0.2_x{dd:g}', i, s - e * g(gl, dd))
        setc(M, 'chong_1', i, 8)
    for i in range(len(NA['T'])):
        setc(NA, 'gated_0.2', i, 0.5); setc(NA, 'ungated_0.2', i, -20)
        for s in range(8): NA['cond']['gated_0.2'][i][s]['mA'] = NA['base'][i][s]['mA'] * 1.3
for acc in ('handover', 'dose'):
    dd = copy.deepcopy(d); M = dd['results']['main']; NA = dd['results']['noadapt']
    scenario(acc)
    json.dump(dd, open(f'synth_{acc}.json', 'w'))
    print('=== scenario:', acc, flush=True)
    subprocess.run([sys.executable, 'analyse_li2017_test2.py', f'synth_{acc}.json', f'synth_{acc}_tests.json'])
